logic [2:0] bitmap_index; // converting degree to the right bitmap
logic [7:0] effective_angle; // the degree in rate (0-90)
logic       is_flipped;      //flag to know if we are in the other half and we need to flip the picture

logic [OBJECT_NUMBER_OF_X_BITS-1:0] read_offset_x;

assign read_offset_x = (is_flipped) ? (OBJECT_WIDTH_X - 1 - offsetX[5:0]) : offsetX[5:0];

logic [3:0] HitIdxX;
logic [3:0] HitIdxY;
assign HitIdxX = read_offset_x >> 2; 
assign HitIdxY = offsetY >> 2;

logic [2:0] raw_hit_code;

always_comb begin
   
	if (degree > 8'd90) begin // left half
        is_flipped = 1'b1;       
        effective_angle = 8'd180 - degree; // convert to (0-90)
		  
    end else begin //right side
        is_flipped = 1'b0;
        effective_angle = degree;
		  
    end
end


always_comb begin
bitmap_index = 3'd6; 

    if      (effective_angle <= 8'd8)  bitmap_index = 3'd6;
    else if (effective_angle <= 8'd22) bitmap_index = 3'd5;
    else if (effective_angle <= 8'd37) bitmap_index = 3'd4;
    else if (effective_angle <= 8'd52) bitmap_index = 3'd3;
    else if (effective_angle <= 8'd67) bitmap_index = 3'd2;
    else if (effective_angle <= 8'd82) bitmap_index = 3'd1;
    else                               bitmap_index = 3'd0; // 83-90+
end
//////////--------------------------------------------------------------------------------------------------------------=

assign raw_hit_code = hit_colors[HitIdxY][HitIdxX];

always_ff@(posedge clk or negedge resetN)
begin
	if(!resetN) begin
		RGBout <=	8'h00;
		HitEdgeCode <= 3'h0;

	end

	else begin
		RGBout <= TRANSPARENT_ENCODING ; // default  
		HitEdgeCode <= 3'h0;


		if (InsideRectangle == 1'b1) begin
            RGBout <= hook_degree[bitmap_index][offsetY][read_offset_x];  
            
				// in case the hook is flipped
            if (is_flipped) begin
                if (raw_hit_code == 3'd4)      HitEdgeCode <= 3'd2;
                else if (raw_hit_code == 3'd2) HitEdgeCode <= 3'd4; 
                else                           HitEdgeCode <= raw_hit_code;
            end 
            else begin
                HitEdgeCode <= raw_hit_code;
            end
            // ---------------------------------------------------
        end
	end
		
end
//////////--------------------------------------------------------------------------------------------------------------=
// decide if to draw the pixel or not 
assign drawingRequest = (RGBout != TRANSPARENT_ENCODING ) ? 1'b1 : 1'b0 ; // get optional transparent command from the bitmpap   

endmodule